{
  "action": "query",
  "q": {
    "select": [
      {"expression": "component.component_code as part_code"},
      {"expression": "sum(model_bom.qty * component_bom.qty) as total_qty"}
    ],
    "from": "company_model",
    "join": [
      {
        "type": "inner",
        "table": "model_bom",
        "on": "company_model.model_id = model_bom.model_id"
      },
      {
        "type": "inner",
        "table": "component",
        "on": "model_bom.component_id = component.component_id"
      },
      {
        "type": "inner",
        "table": "component_bom",
        "on": "component.component_id = component_bom.parent_component_id"
      },
      {
        "type": "inner",
        "table": "component as child_component",
        "on": "component_bom.child_component_id = child_component.component_id"
      }
    ],
    "where": [
      "company_model.model_code = 'TE1-120WAL55-0055'",
      "child_component.component_code = 'TAB-496-BLK-02765'",
      "model_bom.valid_from <= DATE '2026-10-01'",
      "(model_bom.valid_to IS NULL OR model_bom.valid_to >= DATE '2026-10-01')",
      "component_bom.valid_from <= DATE '2026-10-01'",
      "(component_bom.valid_to IS NULL OR component_bom.valid_to >= DATE '2026-10-01')"
    ],
    "group_by": ["component.component_code"]
  }
}

