{"action": "run_sql", "sql": "WITH RECURSIVE lines AS (
 SELECT ol.qty, o.order_date, s.sku_id
 FROM order_line ol JOIN orders o ON o.order_id=ol.order_id JOIN listing l ON l.listing_id=ol.listing_id JOIN sales_sku s ON s.sku_id=l.sku_id
 WHERE o.status='completed' AND o.order_date BETWEEN '2024-01-01' AND '2024-12-31'
  AND o.store_id=(SELECT store_id FROM store WHERE store_name='Walmart-UK-22')
  AND s.sku_code='FOO-140-GRY-02859'
), sku_items AS (
 SELECT l.qty, l.order_date, l.sku_id AS base_sku, l.sku_id AS item_sku, 1 AS mult FROM lines l WHERE NOT EXISTS (SELECT 1 FROM sales_sku WHERE is_bundle AND sku_id=l.sku_id)
 UNION ALL
 SELECT l.qty, l.order_date, l.sku_id, bi.item_sku_id, 1 FROM lines l JOIN bundle_item bi ON bi.bundle_sku_id=l.sku_id
), sku_model AS (
 SELECT si.qty, si.order_date, sm.model_id, si.mult*sm.qty AS q FROM sku_items si JOIN sku_model sm ON sm.sku_id=si.item_sku
), model_comp AS (
 SELECT sm.qty, sm.order_date, mb.component_id, sm.q*mb.qty AS q FROM sku_model sm JOIN model_bom mb ON mb.model_id=sm.model_id AND mb.valid_from<=sm.order_date AND (mb.valid_to IS NULL OR sm.order_date<=mb.valid_to)
), rec AS (
 SELECT qty, order_date, component_id, q FROM model_comp
 UNION ALL
 SELECT r.qty, r.order_date, cb.child_component_id, r.q*cb.qty FROM rec r JOIN component_bom cb ON cb.parent_component_id=r.component_id AND cb.valid_from<=r.order_date AND (cb.valid_to IS NULL OR r.order_date<=cb.valid_to) JOIN component c ON c.component_id=cb.child_component_id AND NOT c.is_assembly
)
SELECT SUM(q) FROM rec JOIN component c ON c.component_id=rec.component_id WHERE c.component_code='FOO-140-GRY-02859'"}

