{"action": "run_sql", "sql": "WITH RECURSIVE top AS (
 SELECT c.component_id, m.qty AS qty FROM model_bom m JOIN company_model cm ON cm.model_id=m.model_id WHERE cm.model_code='CO6-160WHT85-0376' AND m.valid_from<=DATE '2026-03-08' AND (m.valid_to IS NULL OR DATE '2026-03-08'<=m.valid_to)
), path(cid, q) AS (
 SELECT component_id, qty FROM top
 UNION ALL
 SELECT b.child_component_id, p.q*b.qty FROM path p JOIN component_bom b ON b.parent_component_id=p.cid WHERE b.valid_from<=DATE '2026-03-08' AND (b.valid_to IS NULL OR DATE '2026-03-08'<=b.valid_to)
)
SELECT ROUND(SUM(p.q*c.unit_cost),2) AS total_cost FROM path p JOIN component c ON c.component_id=p.cid WHERE c.is_assembly=FALSE"}

